// ============================================
// EINGABE VERARBEITEN & STANDARDWERTE SETZEN
// ============================================

const body = $input.first().json.body || $input.first().json;

// --- Mitarbeiter-Liste ---
// Erwartet: Array von { name, max_stunden, position }
// Falls nicht angegeben, werden Beispiel-Mitarbeiter verwendet
const mitarbeiter = body.mitarbeiter || [
  { name: "Anna Mueller", max_stunden: 40, position: "Rezeption" },
  { name: "Ben Schmidt", max_stunden: 40, position: "Rezeption" },
  { name: "Clara Weber", max_stunden: 30, position: "Housekeeping" },
  { name: "David Fischer", max_stunden: 40, position: "Housekeeping" },
  { name: "Eva Richter", max_stunden: 20, position: "Restaurant" },
  { name: "Felix Koenig", max_stunden: 40, position: "Restaurant" },
  { name: "Greta Hoffmann", max_stunden: 40, position: "Kueche" },
  { name: "Hans Becker", max_stunden: 35, position: "Kueche" }
];

// --- Wochenstart berechnen (naechster Montag falls nicht angegeben) ---
let wocheStart = body.woche_start;
if (!wocheStart) {
  const heute = new Date();
  const wochentag = heute.getDay();
  const diff = wochentag === 0 ? 1 : wochentag === 1 ? 0 : 8 - wochentag;
  const montag = new Date(heute);
  montag.setDate(heute.getDate() + diff);
  wocheStart = montag.toISOString().split("T")[0];
}

// --- Hotel-Auslastung pro Tag (0.0 - 1.0) ---
const auslastung = body.auslastung || {
  Montag: 0.50,
  Dienstag: 0.55,
  Mittwoch: 0.60,
  Donnerstag: 0.65,
  Freitag: 0.85,
  Samstag: 0.95,
  Sonntag: 0.75
};

// --- Events ---
// Format: [{ tag: "Samstag", name: "Hochzeit", gaeste: 120, zusatz_personal: 3 }]
const events = body.events || [];

// --- Schicht-Definitionen ---
const schichten = {
  frueh: { name: "Fruehschicht", start: "06:00", ende: "14:00", stunden: 8 },
  spaet: { name: "Spaetschicht", start: "14:00", ende: "22:00", stunden: 8 },
  nacht: { name: "Nachtschicht", start: "22:00", ende: "06:00", stunden: 8 }
};

return [{
  json: {
    mitarbeiter,
    woche_start: wocheStart,
    auslastung,
    events,
    schichten
  }
}];

// ============================================
// DIENSTPLAN GENERIEREN
// Berechnet Personalbedarf und erstellt Plan
// ============================================

const data = $input.first().json;
const { mitarbeiter, woche_start, auslastung, events, schichten } = data;

const wochentage = ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag"];
const totalMA = mitarbeiter.length;

// ---- SCHRITT 1: Personalbedarf pro Tag berechnen ----
const bedarf = {};

for (const tag of wochentage) {
  const tagesAuslastung = auslastung[tag] !== undefined ? auslastung[tag] : 0.5;
  const tagesEvents = events.filter(e => e.tag === tag);
  const eventBonus = tagesEvents.reduce((sum, e) => sum + (e.zusatz_personal || 0), 0);

  // Basisbedarf skaliert mit Auslastung
  // Fruehschicht: 40% der Kapazitaet (Checkout, Reinigung, Fruehstueck)
  // Spaetschicht: 35% der Kapazitaet (Check-in, Abendservice)
  // Nachtschicht: 15% der Kapazitaet (Rezeption, Sicherheit)
  const basisFrueh = Math.max(2, Math.ceil(totalMA * tagesAuslastung * 0.40));
  const basisSpaet = Math.max(2, Math.ceil(totalMA * tagesAuslastung * 0.35));
  const basisNacht = Math.max(1, Math.ceil(totalMA * tagesAuslastung * 0.15));

  bedarf[tag] = {
    auslastung_prozent: Math.round(tagesAuslastung * 100),
    events: tagesEvents,
    frueh: Math.min(basisFrueh + Math.ceil(eventBonus * 0.4), totalMA),
    spaet: Math.min(basisSpaet + Math.ceil(eventBonus * 0.4), totalMA),
    nacht: Math.min(basisNacht + Math.ceil(eventBonus * 0.2), totalMA)
  };
}

// ---- SCHRITT 2: Mitarbeiter-Status initialisieren ----
const maStatus = mitarbeiter.map((m, i) => ({
  index: i,
  name: m.name,
  position: m.position || "Allgemein",
  max_stunden: m.max_stunden || 40,
  stunden: 0,
  letzte_schicht: null,
  freie_tage: 0,
  arbeitstage: 0,
  counts: { frueh: 0, spaet: 0, nacht: 0 }
}));

// ---- SCHRITT 3: Schichten zuweisen ----
const dienstplan = {};

for (const tag of wochentage) {
  dienstplan[tag] = { frueh: [], spaet: [], nacht: [], frei: [] };
  const zugewiesen = new Set();

  for (const typ of ["frueh", "spaet", "nacht"]) {
    const benoetigte = bedarf[tag][typ];
    const stundenSchicht = schichten[typ].stunden;

    // Verfuegbare Mitarbeiter ermitteln und sortieren
    const verfuegbar = maStatus
      .filter(s => {
        // Bereits heute eingeteilt?
        if (zugewiesen.has(s.index)) return false;
        // Stundenlimit ueberschritten?
        if (s.stunden + stundenSchicht > s.max_stunden) return false;
        // Nach Nachtschicht keine Fruehschicht (Ruhezeit)
        if (typ === "frueh" && s.letzte_schicht === "nacht") return false;
        // Max 6 Arbeitstage pro Woche
        if (s.arbeitstage >= 6) return false;
        return true;
      })
      .sort((a, b) => {
        // 1. Weniger geleistete Stunden bevorzugen
        const stundenDiff = a.stunden - b.stunden;
        if (stundenDiff !== 0) return stundenDiff;
        // 2. Weniger Schichten dieses Typs (faire Rotation)
        const countDiff = a.counts[typ] - b.counts[typ];
        if (countDiff !== 0) return countDiff;
        // 3. Mehr freie Tage = laenger nicht gearbeitet
        return b.freie_tage - a.freie_tage;
      });

    const anzahl = Math.min(benoetigte, verfuegbar.length);
    for (let i = 0; i < anzahl; i++) {
      const ma = verfuegbar[i];
      dienstplan[tag][typ].push({
        name: ma.name,
        position: ma.position,
        von: schichten[typ].start,
        bis: schichten[typ].ende,
        stunden: stundenSchicht
      });
      zugewiesen.add(ma.index);
      maStatus[ma.index].stunden += stundenSchicht;
      maStatus[ma.index].letzte_schicht = typ;
      maStatus[ma.index].counts[typ]++;
      maStatus[ma.index].arbeitstage++;
      maStatus[ma.index].freie_tage = 0;
    }
  }

  // Freie Mitarbeiter markieren
  for (const s of maStatus) {
    if (!zugewiesen.has(s.index)) {
      dienstplan[tag].frei.push(s.name);
      s.letzte_schicht = null;
      s.freie_tage++;
    }
  }
}

// ---- SCHRITT 4: Uebersicht erstellen ----
const uebersicht = maStatus.map(s => ({
  name: s.name,
  position: s.position,
  stunden: s.stunden,
  max_stunden: s.max_stunden,
  auslastung_prozent: Math.round((s.stunden / s.max_stunden) * 100),
  freie_tage: 7 - s.arbeitstage,
  fruehschichten: s.counts.frueh,
  spaetschichten: s.counts.spaet,
  nachtschichten: s.counts.nacht
}));

return [{
  json: {
    woche_start,
    dienstplan,
    bedarf,
    uebersicht
  }
}];

// ============================================
// AUSGABE FORMATIEREN
// Erstellt lesbare Text-Ausgabe des Dienstplans
// ============================================

const data = $input.first().json;
const { woche_start, dienstplan, bedarf, uebersicht } = data;

const wochentage = ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag"];
const startDatum = new Date(woche_start + "T00:00:00");

// --- Header ---
let text = "=".repeat(55) + "\n";
text += "  HOTEL DIENSTPLAN\n";
text += "  Woche ab: " + woche_start + "\n";
text += "  Erstellt: " + new Date().toLocaleString("de-DE") + "\n";
text += "=".repeat(55) + "\n\n";

// --- Tagesplaene ---
for (let i = 0; i < wochentage.length; i++) {
  const tag = wochentage[i];
  const datum = new Date(startDatum);
  datum.setDate(startDatum.getDate() + i);
  const dd = String(datum.getDate()).padStart(2, "0");
  const mm = String(datum.getMonth() + 1).padStart(2, "0");
  const yyyy = datum.getFullYear();

  const b = bedarf[tag];
  text += "-".repeat(55) + "\n";
  text += "  " + tag.toUpperCase() + ", " + dd + "." + mm + "." + yyyy;
  text += " | Auslastung: " + b.auslastung_prozent + "%";
  if (b.events && b.events.length > 0) {
    text += "\n  Events: " + b.events.map(e => e.name + " (" + (e.gaeste || "?") + " Gaeste)").join(", ");
  }
  text += "\n".repeat(2);

  const plan = dienstplan[tag];

  text += "  [F] Fruehschicht  (06:00-14:00) | Bedarf: " + b.frueh + "\n";
  if (plan.frueh.length > 0) {
    for (const m of plan.frueh) {
      text += "      - " + m.name + " (" + m.position + ")\n";
    }
  } else {
    text += "      (keine Zuweisung)\n";
  }

  text += "  [S] Spaetschicht  (14:00-22:00) | Bedarf: " + b.spaet + "\n";
  if (plan.spaet.length > 0) {
    for (const m of plan.spaet) {
      text += "      - " + m.name + " (" + m.position + ")\n";
    }
  } else {
    text += "      (keine Zuweisung)\n";
  }

  text += "  [N] Nachtschicht  (22:00-06:00) | Bedarf: " + b.nacht + "\n";
  if (plan.nacht.length > 0) {
    for (const m of plan.nacht) {
      text += "      - " + m.name + " (" + m.position + ")\n";
    }
  } else {
    text += "      (keine Zuweisung)\n";
  }

  if (plan.frei.length > 0) {
    text += "  [X] Frei: " + plan.frei.join(", ") + "\n";
  }
  text += "\n";
}

// --- Mitarbeiter-Uebersicht ---
text += "=".repeat(55) + "\n";
text += "  MITARBEITER-UEBERSICHT\n";
text += "=".repeat(55) + "\n\n";

for (const ma of uebersicht) {
  text += "  " + ma.name + " (" + ma.position + ")\n";
  text += "    Stunden: " + ma.stunden + "/" + ma.max_stunden + "h";
  text += " (" + ma.auslastung_prozent + "% Auslastung)";
  text += " | Freie Tage: " + ma.freie_tage + "\n";
  text += "    Schichten: F:" + ma.fruehschichten;
  text += " S:" + ma.spaetschichten;
  text += " N:" + ma.nachtschichten + "\n\n";
}

text += "=".repeat(55) + "\n";

return [{
  json: {
    woche_start,
    dienstplan,
    uebersicht,
    dienstplan_text: text
  }
}];

// ============================================
// TESTDATEN FUER MANUELLEN TRIGGER
// ============================================

return [{
  json: {
    body: {
      mitarbeiter: [
        { name: "Anna Mueller", max_stunden: 40, position: "Rezeption" },
        { name: "Ben Schmidt", max_stunden: 40, position: "Rezeption" },
        { name: "Clara Weber", max_stunden: 30, position: "Housekeeping" },
        { name: "David Fischer", max_stunden: 40, position: "Housekeeping" },
        { name: "Eva Richter", max_stunden: 20, position: "Restaurant" },
        { name: "Felix Koenig", max_stunden: 40, position: "Restaurant" },
        { name: "Greta Hoffmann", max_stunden: 40, position: "Kueche" },
        { name: "Hans Becker", max_stunden: 35, position: "Kueche" }
      ],
      woche_start: "2026-02-09",
      auslastung: {
        Montag: 0.50,
        Dienstag: 0.55,
        Mittwoch: 0.60,
        Donnerstag: 0.65,
        Freitag: 0.85,
        Samstag: 0.95,
        Sonntag: 0.75
      },
      events: [
        {
          tag: "Samstag",
          name: "Hochzeitsfeier",
          gaeste: 120,
          zusatz_personal: 3
        },
        {
          tag: "Freitag",
          name: "Firmenkonferenz",
          gaeste: 80,
          zusatz_personal: 2
        }
      ]
    }
  }
}];
